package clusterdata.datatypes;

public class TaskEvent {
    public long timestamp;
    public long jobId;
    public int taskIndex;
    public int eventType;

    public TaskEvent() {}

    public TaskEvent(long timestamp, long jobId, int taskIndex, int eventType) {
        this.timestamp = timestamp;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.eventType = eventType;
    }

    public static TaskEvent fromString(String line) {
        String[] tokens = line.split(",", -1);
        if (tokens.length < 6) return null;
        try {
            long timestamp = Long.parseLong(tokens[0]);
            long jobId = Long.parseLong(tokens[2]);
            int taskIndex = tokens[3].isEmpty() ? -1 : Integer.parseInt(tokens[3]);
            int eventType = Integer.parseInt(tokens[5]);
            return new TaskEvent(timestamp, jobId, taskIndex, eventType);
        } catch (NumberFormatException e) {
            return null;
        }
    }

    @Override
    public String toString() {
        return "TaskEvent{" +
                "timestamp=" + timestamp +
                ", jobId=" + jobId +
                ", taskIndex=" + taskIndex +
                ", eventType=" + eventType +
                '}';
    }
}

