package clusterdata.query;

import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.AggregateFunction;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.CoProcessFunction;
import org.apache.flink.streaming.api.functions.sink.RichSinkFunction;
import org.apache.flink.streaming.api.functions.source.SourceFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.util.Collector;

import java.io.*;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        DataStream<TaskEvent> taskEvents = env.addSource(taskSourceOrTest(new TaskEventSource(taskInput)))
                .filter(t -> t != null && t.eventType == 0) // SUBMIT
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((event, timestamp) -> event.timestamp / 1000)
                );

        DataStream<JobEvent> jobEvents = env.addSource(jobSourceOrTest(new JobEventSource(jobInput)))
                .filter(j -> j != null && j.eventType >= 4) // FINISH, KILL, LOST
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<JobEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((event, timestamp) -> event.timestamp / 1000)
                );

        DataStream<Tuple2<Long, Integer>> stageCounts = taskEvents
                .keyBy(t -> t.jobId)
                .window(EventTimeSessionWindows.withGap(Time.minutes(10)))
                .aggregate(new CountAggregate());

        stageCounts.keyBy(t -> t.f0)
                .connect(jobEvents.keyBy(j -> j.jobId))
                .process(new MaxStageAndFinishProcessFunction())
                .addSink(sinkOrTest(new FileSink(outputPath)))
                .setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

    public static class TaskEventSource implements SourceFunction<TaskEvent> {
        private String filePath;
        public TaskEventSource(String filePath) { this.filePath = filePath; }
        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            if (filePath == null) return;
            try (GZIPInputStream gzipStream = new GZIPInputStream(new FileInputStream(filePath));
                 BufferedReader reader = new BufferedReader(new InputStreamReader(gzipStream))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    TaskEvent event = TaskEvent.fromString(line);
                    if (event != null) {
                        ctx.collectWithTimestamp(event, event.timestamp / 1000);
                    }
                }
            }
        }
        @Override
        public void cancel() {}
    }

    public static class JobEventSource implements SourceFunction<JobEvent> {
        private String filePath;
        public JobEventSource(String filePath) { this.filePath = filePath; }
        @Override
        public void run(SourceContext<JobEvent> ctx) throws Exception {
            if (filePath == null) return;
            try (GZIPInputStream gzipStream = new GZIPInputStream(new FileInputStream(filePath));
                 BufferedReader reader = new BufferedReader(new InputStreamReader(gzipStream))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    JobEvent event = JobEvent.fromString(line);
                    if (event != null) {
                        ctx.collectWithTimestamp(event, event.timestamp / 1000);
                    }
                }
            }
        }
        @Override
        public void cancel() {}
    }

    public static class CountAggregate implements AggregateFunction<TaskEvent, Integer, Integer> {
        @Override
        public Integer createAccumulator() { return 0; }
        @Override
        public Integer add(TaskEvent value, Integer accumulator) { return accumulator + 1; }
        @Override
        public Integer getResult(Integer accumulator) { return accumulator; }
        @Override
        public Integer merge(Integer a, Integer b) { return a + b; }
    }

    public static class MaxStageAndFinishProcessFunction extends CoProcessFunction<Tuple2<Long, Integer>, JobEvent, Tuple2<Long, Integer>> {
        private ValueState<Integer> maxCount;
        private ValueState<Boolean> finished;

        @Override
        public void open(Configuration parameters) throws Exception {
            maxCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxCount", Integer.class));
            finished = getRuntimeContext().getState(new ValueStateDescriptor<>("finished", Boolean.class));
        }

        @Override
        public void processElement1(Tuple2<Long, Integer> value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            Integer currentMax = maxCount.value();
            if (currentMax == null || value.f1 > currentMax) {
                maxCount.update(value.f1);
            }
        }

        @Override
        public void processElement2(JobEvent value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            if (finished.value() == null || !finished.value()) {
                finished.update(true);
                // Set timer for T + 10min + 1s to allow session windows to close
                ctx.timerService().registerEventTimeTimer(ctx.timestamp() + 601000);
            }
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            Integer finalMax = maxCount.value();
            if (finalMax != null) {
                out.collect(new Tuple2<>(ctx.getCurrentKey(), finalMax));
            }
            maxCount.clear();
            finished.clear();
        }
    }

    public static class FileSink extends RichSinkFunction<Tuple2<Long, Integer>> {
        private String path;
        private transient PrintWriter writer;

        public FileSink(String path) {
            this.path = path;
        }

        @Override
        public void open(Configuration parameters) throws Exception {
            writer = new PrintWriter(new BufferedWriter(new FileWriter(path)));
        }

        @Override
        public void invoke(Tuple2<Long, Integer> value, Context context) throws Exception {
            writer.println("(" + value.f0 + "," + value.f1 + ")");
            writer.flush();
        }

        @Override
        public void close() throws Exception {
            if (writer != null) {
                writer.close();
            }
        }
    }
}

