import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.util.Collector;

import java.io.*;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        DataStream<TaskEvent> taskEvents = env.addSource(taskSourceOrTest(new TaskEventSource(taskInput)))
                .filter(t -> t != null && t.eventType == 0) // SUBMIT
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((event, timestamp) -> event.timestamp / 1000)
                );

        DataStream<JobEvent> jobEvents = env.addSource(jobSourceOrTest(new JobEventSource(jobInput)))
                .filter(j -> j != null && j.eventType >= 4) // FINISH, KILL, LOST
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<JobEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((event, timestamp) -> event.timestamp / 1000)
                );

        DataStream<Tuple2<Long, Integer>> stageCounts = taskEvents
                .keyBy(t -> t.jobId)
                .window(EventTimeSessionWindows.withGap(Time.minutes(10)))
                .aggregate(new CountAggregate());

        stageCounts.keyBy(t -> t.f0)
                .connect(jobEvents.keyBy(j -> j.jobId))
                .process(new MaxStageAndFinishProcessFunction())
                .addSink((SinkFunction<Tuple2<Long, Integer>>) sinkOrTest(new FileSink(outputPath)))
                .setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

    public static class TaskEventSource implements SourceFunction<TaskEvent> {
        private String filePath;
        public TaskEventSource(String filePath) { this.filePath = filePath; }
        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            if (filePath == null) return;
            try (GZIPInputStream gzipStream = new GZIPInputStream(new FileInputStream(filePath));
                 BufferedReader reader = new BufferedReader(new InputStreamReader(gzipStream))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    TaskEvent event = TaskEvent.fromString(line);
                    if (event != null) {
                        ctx.collectWithTimestamp(event, event.timestamp / 1000);
                    }
                }
            }
        }
        @Override
        public void cancel() {}
    }

    public static class JobEventSource implements SourceFunction<JobEvent> {
        private String filePath;
        public JobEventSource(String filePath) { this.filePath = filePath; }
        @Override
        public void run(SourceContext<JobEvent> ctx) throws Exception {
            if (filePath == null) return;
            try (GZIPInputStream gzipStream = new GZIPInputStream(new FileInputStream(filePath));
                 BufferedReader reader = new BufferedReader(new InputStreamReader(gzipStream))) {
                String line;
                while ((line = reader.readLine()) != null) {
