        @Override
        public Integer createAccumulator() { return 0; }
        @Override
        public Integer add(TaskEvent value, Integer accumulator) { return accumulator + 1; }
        @Override
        public Integer getResult(Integer accumulator) { return accumulator; }
        @Override
        public Integer merge(Integer a, Integer b) { return a + b; }
    }

    public static class MaxStageAndFinishProcessFunction extends CoProcessFunction<Tuple2<Long, Integer>, JobEvent, Tuple2<Long, Integer>> {
        private ValueState<Integer> maxCount;
        private ValueState<Boolean> finished;

        @Override
        public void open(Configuration parameters) throws Exception {
            maxCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxCount", Integer.class));
            finished = getRuntimeContext().getState(new ValueStateDescriptor<>("finished", Boolean.class));
        }

        @Override
        public void processElement1(Tuple2<Long, Integer> value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            Integer currentMax = maxCount.value();
            if (currentMax == null || value.f1 > currentMax) {
                maxCount.update(value.f1);
            }
        }

        @Override
        public void processElement2(JobEvent value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            if (finished.value() == null || !finished.value()) {
                finished.update(true);
                // Set timer for T + 10min + 1s to allow session windows to close
                ctx.timerService().registerEventTimeTimer(ctx.timestamp() + 601000);
            }
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            Integer finalMax = maxCount.value();
            if (finalMax != null) {
                out.collect(new Tuple2<>(ctx.getCurrentKey(), finalMax));
            }
            maxCount.clear();
            finished.clear();
        }
    }

    public static class FileSink extends RichSinkFunction<Tuple2<Long, Integer>> {
        private String path;
        private transient PrintWriter writer;

        public FileSink(String path) {
            this.path = path;
        }

        @Override
        public void open(Configuration parameters) throws Exception {
            writer = new PrintWriter(new BufferedWriter(new FileWriter(path)));
        }

        @Override
        public void invoke(Tuple2<Long, Integer> value, Context context) throws Exception {
            writer.println("(" + value.f0 + "," + value.f1 + ")");
            writer.flush();
        }

        @Override
        public void close() throws Exception {
            if (writer != null) {
                writer.close();
            }
        }
    }
}

